SET default_transaction_read_only = on;
SELECT ticker, trade_date, close FROM mi_daily_closes WHERE ticker = ANY(ARRAY['AG','AMAL','AMTB','BANR','BUSE','CATY','CBC','CBSH','CDE','CHCO','CLBK','CNMD','CNOB','CUBI','CVBF','DCOM','EBC','EGBN','ESQ','EWBC','EXK','FBNC','FBP','FCF','FIBK','FSM','FSUN','GMED','HBNC','HIFS','HL','HOMB','HOPE','HWC','INDB','KEY','MCB','NBN','NBTB','NIC','NWBI','OFG','OSBC','OZK','PAAS','PB','PFBC','PNFP','QCRH','RBCAA','SFNC','SIBN','SNN','STBA','SYK','TCBI','TRMK','UBSI','UCB','WABC','ZBH']) AND trade_date IN (DATE '2026-11-04', DATE '2026-11-03', DATE '2026-10-28', DATE '2026-10-06', DATE '2025-12-31') ORDER BY 1,2;
SELECT DISTINCT trade_date FROM mi_daily_closes WHERE trade_date <= DATE '2026-11-04' AND trade_date >= DATE '2026-09-20' ORDER BY 1 DESC LIMIT 22;
